"""Input handling: paths, stdin, gzip, decoding (SPEC section 5).

Two decisions shape this module.

*Open eagerly, read lazily.* SPEC 5 requires a missing, unreadable, or
malformed-gzip input to exit 2 **before any output**, so the CLI opens every
input up front and only then starts streaming. For a ``.gz`` that means
pulling one byte through the decompressor at open time, because the gzip
header is not checked until something is read.

*Be dumb about blank lines.* Every line is yielded, blank or not, so line
numbers are the file's own. Counting blanks is the pipeline's job. If the
reader dropped them, the sniff sample replayed in front of the remainder
would either double-count them or shift every line number after it.
"""

from __future__ import annotations

import gzip
import io
import sys
from collections.abc import Iterator
from types import TracebackType
from typing import IO, cast

STDIN_NAME = "-"
GZIP_SUFFIX = ".gz"
ENCODING = "utf-8"
# SPEC 5: a binary chunk mid-log degrades into replacement characters rather
# than ending the run.
DECODE_ERRORS = "replace"


class InputError(Exception):
    """An input could not be opened. The CLI turns this into exit code 2."""


class Source:
    """One opened input: its display name and its lines.

    ``name`` is what the record's ``source`` will be -- the path as given, or
    ``-`` for stdin.
    """

    __slots__ = ("_owned", "_stream", "name")

    def __init__(self, name: str, stream: IO[str], *, owned: bool) -> None:
        self.name = name
        self._stream = stream
        # stdin belongs to the interpreter: several inputs may be given, and
        # closing one of them must not close the process's stdin.
        self._owned = owned

    def lines(self) -> Iterator[tuple[int, str]]:
        """Yield ``(lineno, text)`` for every line, newline stripped.

        ``lineno`` is 1-based within this source (SPEC 3). Universal newline
        translation has already turned ``\\r\\n`` and a lone ``\\r`` into
        ``\\n``, so one ``removesuffix`` is the whole of the stripping.
        """
        for lineno, line in enumerate(self._stream, start=1):
            yield lineno, line.removesuffix("\n")

    def close(self) -> None:
        if self._owned:
            self._stream.close()

    def __enter__(self) -> Source:
        return self

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        tb: TracebackType | None,
    ) -> None:
        self.close()


def open_source(path: str) -> Source:
    """Open one input, or raise :class:`InputError` naming path and cause.

    ``-`` is stdin. A name ending in ``.gz`` is read through :mod:`gzip`, by
    suffix only and never by magic bytes (SPEC 5), so compressed content under
    a plain name decodes to replacement characters instead of being guessed at.
    """
    if path == STDIN_NAME:
        return Source(STDIN_NAME, _decode(sys.stdin.buffer), owned=False)
    if path.endswith(GZIP_SUFFIX):
        return Source(path, _decode(_open_gzip(path)), owned=True)
    try:
        # The handle outlives this call by design; `Source` owns closing it,
        # because SPEC 5 wants every input opened before any of them is read.
        binary = open(path, "rb")  # noqa: SIM115
    except OSError as exc:
        raise InputError(_message(path, exc)) from exc
    return Source(path, _decode(binary), owned=True)


def _open_gzip(path: str) -> IO[bytes]:
    """Open a gzip file with its header already validated.

    ``gzip.open`` does no work until the first read, so a file that is not
    gzip at all would otherwise surface as an error halfway through a run,
    after output had been written. One byte read and a seek back to the start
    forces the check while there is still nothing on stdout to contradict.
    """
    try:
        binary = gzip.open(path, "rb")  # noqa: SIM115 - closed by `Source`
    except OSError as exc:
        raise InputError(_message(path, exc)) from exc
    try:
        binary.read(1)
        binary.seek(0)
    except (OSError, EOFError) as exc:
        binary.close()
        raise InputError(_message(path, exc)) from exc
    # `GzipFile` is a `BufferedIOBase`, which reads and closes like any other
    # binary handle; typeshed just does not describe it as an `IO[bytes]`.
    return cast(IO[bytes], binary)


def _decode(binary: IO[bytes]) -> IO[str]:
    return io.TextIOWrapper(binary, encoding=ENCODING, errors=DECODE_ERRORS)


def _message(path: str, exc: BaseException) -> str:
    """``path: reason``, preferring the OS error text over a repr."""
    reason = getattr(exc, "strerror", None) or str(exc) or type(exc).__name__
    return f"{path}: {reason}"
"""Choosing a parser for one source by sampling it (SPEC 5.1).

The sample must not be consumed: the first hundred lines are ordinary lines
and have to be parsed like any other. So the buffered pairs are chained back
in front of the remaining iterator, which works the same for a file and for
stdin, where seeking back is not an option.

Line numbers survive that replay because the buffer holds the
``(lineno, text)`` pairs the reader produced, not just the text. Blank lines
are buffered like the rest but kept out of the sample, since SPEC 4.2 promises
``can_parse`` up to a hundred *non-empty* lines.
"""

from __future__ import annotations

from collections.abc import Iterable, Iterator
from itertools import chain

from logsift.plugin import LoadedParser, Registry, WarnFn, warn_stderr

SAMPLE_SIZE = 100
_QUOTE_LIMIT = 120

Lines = Iterable[tuple[int, str]]


class NoParserClaimed(Exception):
    """No loaded parser recognised a source. The CLI turns this into exit 2."""


def is_blank(text: str) -> bool:
    """Whether a line counts as blank for sampling and for the line counters.

    Whitespace-only is blank: a line of spaces tells a parser nothing about
    the format, and reporting it as a parse error would be noise.
    """
    return not text.strip()


def sniff(
    registry: Registry,
    lines: Lines,
    *,
    source: str,
    warn: WarnFn = warn_stderr,
) -> tuple[LoadedParser, Iterator[tuple[int, str]]]:
    """Pick a parser for ``source`` and return it with every line intact.

    Candidates are tried in descending priority (SPEC 5.1) and the first to
    claim the sample wins, so a lower-priority parser is never consulted once
    one has. A ``can_parse`` that raises disqualifies only that parser, with a
    warning; the run continues (SPEC 4.3).
    """
    buffered, remaining = _take_sample(lines)
    sample = [text for _, text in buffered if not is_blank(text)]
    for entry in registry.sniff_order():
        if _claims(entry, sample, source=source, warn=warn):
            return entry, chain(buffered, remaining)
    raise NoParserClaimed(_no_claim_message(registry, sample, source))


def _take_sample(
    lines: Lines,
) -> tuple[list[tuple[int, str]], Iterator[tuple[int, str]]]:
    """Buffer until ``SAMPLE_SIZE`` non-empty lines are seen, or the input ends.

    Pulling stops at that point rather than reading the whole source, which is
    what keeps sniffing constant-memory on a file of any size (SPEC 1.1).
    """
    remaining = iter(lines)
    buffered: list[tuple[int, str]] = []
    seen = 0
    for pair in remaining:
        buffered.append(pair)
        if not is_blank(pair[1]):
            seen += 1
            if seen == SAMPLE_SIZE:
                break
    return buffered, remaining


def _claims(
    entry: LoadedParser, sample: list[str], *, source: str, warn: WarnFn
) -> bool:
    try:
        return bool(entry.parser.can_parse(sample))
    except Exception as exc:
        # Broad by design: SPEC 4.3 says an exception from can_parse costs the
        # parser this source and nothing more.
        warn(
            f"{source}: parser {entry.name!r} from {entry.dist} raised "
            f"{type(exc).__name__}: {exc} from can_parse; not considering it "
            f"for this input"
        )
        return False


def _no_claim_message(registry: Registry, sample: list[str], source: str) -> str:
    """SPEC 5.1: name what was rejected and show what it was rejecting."""
    names = registry.names()
    available = (
        f"loaded parsers: {', '.join(names)}" if names else "no parsers are installed"
    )
    if not sample:
        return (
            f"{source}: no parser claimed this input, which has no non-empty "
            f"lines ({available})"
        )
    return (
        f"{source}: no parser claimed this input ({available}); "
        f"first line: {_quote(sample[0])}"
    )


def _quote(line: str) -> str:
    """The first line, shortened, so one minified log line is not the message."""
    if len(line) > _QUOTE_LIMIT:
        return f"{line[:_QUOTE_LIMIT]}..."
    return line
"""``--agg``: the spec, and the four aggregators behind it (SPEC 9).

Aggregation runs after filtering and replaces record output, but it borrows
the filter's value layer wholesale: the group key is
:func:`~logsift.expr.eval.render_filter_str` and the percentile input is
:func:`~logsift.expr.eval.coerce_number`, so "grouped together" and "skipped
as non-numeric" mean exactly what they mean in a filter. There is no second
copy of SPEC 6.3 here.

Both memory-hungry aggregations are honest about it (SPEC 9.1): they warn at a
documented size and keep going, because a tool that refuses at a threshold is
a tool that cannot answer the question at all.
"""

from __future__ import annotations

import statistics
from abc import ABC, abstractmethod
from array import array
from collections import Counter
from dataclasses import dataclass

from logsift.expr.eval import MISSING, coerce_number, render_filter_str, resolve_field
from logsift.expr.lexer import is_field_name
from logsift.plugin import WarnFn, warn_stderr
from logsift.record import Record

# SPEC 9: a record whose group field is absent or None is not dropped.
MISSING_GROUP = "<missing>"
# SPEC 9.1: one counter per distinct key, and 8 bytes per buffered value.
GROUP_WARNING_AT = 1_000_000
VALUE_WARNING_AT = 10_000_000

_PERCENTILES = {"p50": 49, "p95": 94}


class AggSpecError(Exception):
    """A malformed ``--agg`` spec. The CLI turns this into exit 1."""


@dataclass(frozen=True, slots=True)
class ScalarResult:
    """One labelled number. ``value`` is ``None`` for a percentile of nothing."""

    label: str
    value: float | int | None


@dataclass(frozen=True, slots=True)
class GroupResult:
    """Rows of ``(key, count)``, already in SPEC 9's display order."""

    field: str
    rows: tuple[tuple[str, int], ...]


AggResult = ScalarResult | GroupResult


class Aggregator(ABC):
    """Fed every matched record, then asked once for its answer."""

    @abstractmethod
    def add(self, record: Record) -> None: ...

    @abstractmethod
    def result(self) -> AggResult: ...

    def notes(self) -> list[str]:
        """Lines for the stderr summary, if this run earned any (SPEC 8.4)."""
        return []


class Count(Aggregator):
    """``count``: how many records reached the aggregator."""

    def __init__(self) -> None:
        self._count = 0

    def add(self, record: Record) -> None:
        self._count += 1

    def result(self) -> AggResult:
        return ScalarResult("count", self._count)


class CountBy(Aggregator):
    """``count by FIELD`` and, with a limit, ``top N FIELD``."""

    def __init__(
        self, field: str, *, limit: int | None = None, warn: WarnFn = warn_stderr
    ) -> None:
        self._field = field
        self._limit = limit
        self._warn = warn
        self._counts: Counter[str] = Counter()
        self._warned = False

    def add(self, record: Record) -> None:
        self._counts[self._key(record)] += 1
        if not self._warned and len(self._counts) > GROUP_WARNING_AT:
            self._warned = True
            self._warn(
                f"count by {self._field}: more than {GROUP_WARNING_AT} distinct "
                f"groups, one counter each; memory grows with the field's "
                f"cardinality"
            )

    def _key(self, record: Record) -> str:
        value = resolve_field(record, self._field)
        if value is MISSING:
            return MISSING_GROUP
        # A value with no string form answers UNKNOWN to every filter, so it
        # is missing here for the same reason: nothing can be said about it.
        return render_filter_str(value) or MISSING_GROUP

    def result(self) -> AggResult:
        # SPEC 9: count descending, then key ascending. Fully deterministic,
        # so a golden test and a diff across runs both stay stable.
        rows = sorted(self._counts.items(), key=lambda item: (-item[1], item[0]))
        if self._limit is not None:
            rows = rows[: self._limit]
        return GroupResult(self._field, tuple(rows))


class Percentile(Aggregator):
    """``p50 FIELD`` / ``p95 FIELD``, exact rather than estimated (SPEC 9.1)."""

    def __init__(self, label: str, field: str, *, warn: WarnFn = warn_stderr) -> None:
        self._label = label
        self._index = _PERCENTILES[label]
        self._field = field
        self._warn = warn
        # 8 bytes a value, which is the number SPEC 9.1's warning is about.
        self._values = array("d")
        self._skipped = 0
        self._warned = False

    def add(self, record: Record) -> None:
        value = resolve_field(record, self._field)
        number = None if value is MISSING else coerce_number(value)
        if number is None:
            self._skipped += 1
            return
        self._values.append(number)
        if not self._warned and len(self._values) > VALUE_WARNING_AT:
            self._warned = True
            self._warn(
                f"{self._label} {self._field}: buffering more than "
                f"{VALUE_WARNING_AT} values ({len(self._values) * 8 // 1_000_000} MB "
                f"and growing); an exact percentile keeps every value"
            )

    def result(self) -> AggResult:
        if not self._values:
            return ScalarResult(self._label, None)
        if len(self._values) == 1:
            # `statistics.quantiles` requires two data points, and the answer
            # for one is not in doubt.
            return ScalarResult(self._label, self._values[0])
        cuts = statistics.quantiles(self._values, n=100, method="inclusive")
        return ScalarResult(self._label, cuts[self._index])

    def notes(self) -> list[str]:
        if not self._skipped:
            return []
        return [
            f"{self._label} {self._field}: {self._skipped} values skipped as "
            f"non-numeric"
        ]


def parse_agg_spec(text: str, *, warn: WarnFn = warn_stderr) -> Aggregator:
    """Read a ``--agg`` spec, raising :class:`AggSpecError` (SPEC 9).

    Keywords are case-insensitive, matching the filter language's ``and`` /
    ``or`` / ``not``. Field names are validated by the lexer's rule, so what
    counts as a name is the same thing in both flags.
    """
    words = text.split()
    if not words:
        raise AggSpecError(_bad(text, "an aggregation was expected"))
    head = words[0].lower()
    if head == "count":
        return _parse_count(text, words, warn=warn)
    if head == "top":
        return _parse_top(text, words, warn=warn)
    if head in _PERCENTILES:
        return Percentile(head, _field(text, words, expected=2), warn=warn)
    raise AggSpecError(
        _bad(text, f"unknown aggregation {words[0]!r}; expected {_KNOWN}")
    )


_KNOWN = "count, count by FIELD, top N FIELD, p50 FIELD, or p95 FIELD"


def _parse_count(text: str, words: list[str], *, warn: WarnFn) -> Aggregator:
    if len(words) == 1:
        return Count()
    if words[1].lower() != "by":
        raise AggSpecError(_bad(text, "expected 'count' or 'count by FIELD'"))
    return CountBy(_field(text, words, expected=3), warn=warn)


def _parse_top(text: str, words: list[str], *, warn: WarnFn) -> Aggregator:
    field = _field(text, words, expected=3)
    try:
        limit = int(words[1])
    except ValueError:
        raise AggSpecError(
            _bad(text, f"expected a whole number of rows, not {words[1]!r}")
        ) from None
    if limit < 1:
        raise AggSpecError(_bad(text, "expected a row count of 1 or more"))
    return CountBy(field, limit=limit, warn=warn)


def _field(text: str, words: list[str], *, expected: int) -> str:
    """The trailing FIELD of a spec, once the word count is right."""
    if len(words) != expected:
        raise AggSpecError(_bad(text, f"expected {_KNOWN}"))
    name = words[-1]
    if not is_field_name(name):
        raise AggSpecError(_bad(text, f"{name!r} is not a field name"))
    return name


def _bad(text: str, reason: str) -> str:
    return f"bad aggregation {text!r}: {reason}"

