# SPEC 9: a record whose group field is absent or None is not dropped.
MISSING_GROUP = "<missing>"
# SPEC 9.1: one counter per distinct key, and 8 bytes per buffered value.
GROUP_WARNING_AT = 1_000_000
VALUE_WARNING_AT = 10_000_000

_PERCENTILES = {"p50": 49, "p95": 94}


class AggSpecError(Exception):
    """A malformed ``--agg`` spec. The CLI turns this into exit 1."""


@dataclass(frozen=True, slots=True)
class ScalarResult:
    """One labelled number. ``value`` is ``None`` for a percentile of nothing."""

    label: str
    value: float | int | None


@dataclass(frozen=True, slots=True)
class GroupResult:
    """Rows of ``(key, count)``, already in SPEC 9's display order."""

    field: str
    rows: tuple[tuple[str, int], ...]


AggResult = ScalarResult | GroupResult


class Aggregator(ABC):
    """Fed every matched record, then asked once for its answer."""

    @abstractmethod
    def add(self, record: Record) -> None: ...

    @abstractmethod
    def result(self) -> AggResult: ...

    def notes(self) -> list[str]:
        """Lines for the stderr summary, if this run earned any (SPEC 8.4)."""
        return []


class Count(Aggregator):
    """``count``: how many records reached the aggregator."""

    def __init__(self) -> None:
        self._count = 0

    def add(self, record: Record) -> None:
        self._count += 1

    def result(self) -> AggResult:
        return ScalarResult("count", self._count)


class CountBy(Aggregator):
    """``count by FIELD`` and, with a limit, ``top N FIELD``."""

    def __init__(
        self, field: str, *, limit: int | None = None, warn: WarnFn = warn_stderr
    ) -> None:
        self._field = field
        self._limit = limit
        self._warn = warn
        self._counts: Counter[str] = Counter()
        self._warned = False

    def add(self, record: Record) -> None:
        self._counts[self._key(record)] += 1
        if not self._warned and len(self._counts) > GROUP_WARNING_AT:
            self._warned = True
            self._warn(
                f"count by {self._field}: more than {GROUP_WARNING_AT} distinct "
                f"groups, one counter each; memory grows with the field's "
                f"cardinality"
            )

    def _key(self, record: Record) -> str:
        value = resolve_field(record, self._field)
        if value is MISSING:
            return MISSING_GROUP
        # A value with no string form answers UNKNOWN to every filter, so it
        # is missing here for the same reason: nothing can be said about it.
        return render_filter_str(value) or MISSING_GROUP

    def result(self) -> AggResult:
        # SPEC 9: count descending, then key ascending. Fully deterministic,
        # so a golden test and a diff across runs both stay stable.
        rows = sorted(self._counts.items(), key=lambda item: (-item[1], item[0]))
        if self._limit is not None:
            rows = rows[: self._limit]
        return GroupResult(self._field, tuple(rows))


class Percentile(Aggregator):
    """``p50 FIELD`` / ``p95 FIELD``, exact rather than estimated (SPEC 9.1)."""

    def __init__(self, label: str, field: str, *, warn: WarnFn = warn_stderr) -> None:
        self._label = label
        self._index = _PERCENTILES[label]
        self._field = field
        self._warn = warn
        # 8 bytes a value, which is the number SPEC 9.1's warning is about.
        self._values = array("d")
        self._skipped = 0
        self._warned = False

    def add(self, record: Record) -> None:
        value = resolve_field(record, self._field)
        number = None if value is MISSING else coerce_number(value)
        if number is None:
            self._skipped += 1
            return
        self._values.append(number)
        if not self._warned and len(self._values) > VALUE_WARNING_AT:
            self._warned = True
            self._warn(
                f"{self._label} {self._field}: buffering more than "
                f"{VALUE_WARNING_AT} values ({len(self._values) * 8 // 1_000_000} MB "
                f"and growing); an exact percentile keeps every value"
            )

    def result(self) -> AggResult:
        if not self._values:
            return ScalarResult(self._label, None)
        if len(self._values) == 1:
            # `statistics.quantiles` requires two data points, and the answer
            # for one is not in doubt.
            return ScalarResult(self._label, self._values[0])
        cuts = statistics.quantiles(self._values, n=100, method="inclusive")
        return ScalarResult(self._label, cuts[self._index])

    def notes(self) -> list[str]:
        if not self._skipped:
            return []
        return [
            f"{self._label} {self._field}: {self._skipped} values skipped as "
            f"non-numeric"
        ]


def parse_agg_spec(text: str, *, warn: WarnFn = warn_stderr) -> Aggregator:
    """Read a ``--agg`` spec, raising :class:`AggSpecError` (SPEC 9).

    Keywords are case-insensitive, matching the filter language's ``and`` /
    ``or`` / ``not``. Field names are validated by the lexer's rule, so what
    counts as a name is the same thing in both flags.
    """
    words = text.split()
    if not words:
        raise AggSpecError(_bad(text, "an aggregation was expected"))
    head = words[0].lower()
    if head == "count":
        return _parse_count(text, words, warn=warn)
    if head == "top":
        return _parse_top(text, words, warn=warn)
    if head in _PERCENTILES:
        return Percentile(head, _field(text, words, expected=2), warn=warn)
    raise AggSpecError(
        _bad(text, f"unknown aggregation {words[0]!r}; expected {_KNOWN}")
    )


_KNOWN = "count, count by FIELD, top N FIELD, p50 FIELD, or p95 FIELD"


def _parse_count(text: str, words: list[str], *, warn: WarnFn) -> Aggregator:
    if len(words) == 1:
        return Count()
    if words[1].lower() != "by":
        raise AggSpecError(_bad(text, "expected 'count' or 'count by FIELD'"))
    return CountBy(_field(text, words, expected=3), warn=warn)


def _parse_top(text: str, words: list[str], *, warn: WarnFn) -> Aggregator:
    field = _field(text, words, expected=3)
    try:
        limit = int(words[1])
    except ValueError:
        raise AggSpecError(
            _bad(text, f"expected a whole number of rows, not {words[1]!r}")
        ) from None
    if limit < 1:
        raise AggSpecError(_bad(text, "expected a row count of 1 or more"))
    return CountBy(field, limit=limit, warn=warn)


def _field(text: str, words: list[str], *, expected: int) -> str:
    """The trailing FIELD of a spec, once the word count is right."""
    if len(words) != expected:
        raise AggSpecError(_bad(text, f"expected {_KNOWN}"))
    name = words[-1]
    if not is_field_name(name):
        raise AggSpecError(_bad(text, f"{name!r} is not a field name"))
    return name


def _bad(text: str, reason: str) -> str:
    return f"bad aggregation {text!r}: {reason}"

